function cdqPdfDriveViewUrlV2287(id){
  id=String(id||'');
  if(!/^[A-Za-z0-9_-]+$/.test(id))throw new Error('Identifiant PDF invalide.');
  return 'https://drive.google.com/file/d/'+id+'/view?usp=drivesdk';
}

function cdqPdfDriveDownloadIntentV2287(id){
  id=String(id||'');
  const fallback=cdqPdfDriveViewUrlV2287(id);

  // Important : le compte Google doit être choisi par l'application Drive,
  // exactement comme Sheets choisit son compte via l'application Sheets.
  // On cible donc le package Google Drive et non la connexion Web GSI.
  const direct='intent://drive.google.com/uc?export=download&id='+encodeURIComponent(id)+
    '#Intent;scheme=https;package=com.google.android.apps.docs;'+
    'action=android.intent.action.VIEW;type=application/pdf;'+
    'S.browser_fallback_url='+encodeURIComponent(fallback)+';end';

  return direct;
}

function cdqPdfMarkOpenedV2287(id){
  if(String(utilisateurCourantRole||'')==='lecture')return;
  try{
    fichierOuvertPourModification=id;
    const meta=cdqDocumentMeta(id)||{};
    sessionStorage.setItem('fichierEnModification',id);
    sessionStorage.setItem('ancienneDateModification',String(meta.dateModification||''));
    sessionStorage.setItem('momentModification',String(Date.now()));
  }catch(_){}
}

function cdqOpenPdfNativeV2287(id){
  const pref=typeof cdqPdfReaderPreference==='function'
    ? cdqPdfReaderPreference()
    : 'ask';

  // Pour l'instant on valide d'abord le mode Demander.
  // Les autres préférences restent sur le chemin Drive stable.
  if(pref!=='ask'){
    const a=document.createElement('a');
    a.href=cdqPdfDriveViewUrlV2287(id);
    a.target='_blank';
    a.rel='noopener';
    document.body.appendChild(a);
    a.click();
    a.remove();
    cdqPdfMarkOpenedV2287(id);
    return;
  }

  cdqPdfMarkOpenedV2287(id);

  const a=document.createElement('a');
  a.href=cdqPdfDriveDownloadIntentV2287(id);
  a.target='_blank';
  a.rel='noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
}

const cdqV19OldModify=window.modifierFichier;
window.modifierFichier=function(id){
  const meta=cdqDocumentMeta(id);

  // Google Sheets : chemin d'origine inchangé.
  if(meta&&meta.type==='GOOGLE_SHEETS'){
    cdqV19OpenOfflineSheet(id);
    return;
  }

  if(meta&&meta.type==='PDF'){
    if(navigator.onLine!==false && /Android/i.test(navigator.userAgent||'')){
      cdqOpenPdfNativeV2287(id);
      return;
    }

    if(navigator.onLine!==false)return cdqV19OldModify(id);
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  if(!navigator.onLine){
    afficherMessage('Ouvrez ce fichier dans son application après l’avoir enregistré sur le téléphone.',false);
    return;
  }

  return cdqV19OldModify(id);
};

